const D = { energy: .5, scale: 1, density: .5, speed: 1, dry: .6, hue: 34, x: .5, y: .42, style: 'playa', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- A dried lakebed running away to the vanishing point. The polygon net is not a tiling —
// it is what a drying mud sheet DOES: it shrinks, fails in tension, and the cracks meet at
// roughly 120 degrees, then the plates curl their edges up off the bed so each one throws a
// little shadow and catches the sun on its lip. Salt has crept out along every crack.
// ONLY BELOW THE HORIZON — above stays fully transparent so the bg slot shows through. ----

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height), sd = P.seed|0;
function hsh(ix,iy){ let h=(Math.imul(ix,374761393)+Math.imul(iy,668265263)+Math.imul(sd,1442695041))|0;
  h=Math.imul(h^(h>>>13),1274126177)|0; return ((h^(h>>>16))>>>0)/4294967295; }   // >>> : a >> fold caps the hash at 0.5
function vn(x,y){ const ix=Math.floor(x), iy=Math.floor(y), fx=x-ix, fy=y-iy;
  const wx=fx*fx*(3-2*fx), wy=fy*fy*(3-2*fy);
  const a=hsh(ix,iy), b=hsh(ix+1,iy), c=hsh(ix,iy+1), d=hsh(ix+1,iy+1);
  return a+(b-a)*wx+(c-a)*wy+(a-b-c+d)*wx*wy; }
function fbm(x,y){ return .55*vn(x,y)+.28*vn(x*2.03+5.1,y*2.03-3.3)+.17*vn(x*4.07-2.7,y*4.07+7.9); }
function hsv(h,s,v){ h=(((h%360)+360)%360)/60; const c=v*s, xx=c*(1-Math.abs(h%2-1)), m=v-c;
  let r,g2,b2;
  if(h<1){r=c;g2=xx;b2=0}else if(h<2){r=xx;g2=c;b2=0}else if(h<3){r=0;g2=c;b2=xx}
  else if(h<4){r=0;g2=xx;b2=c}else if(h<5){r=xx;g2=0;b2=c}else{r=c;g2=0;b2=xx}
  return [(r+m)*255,(g2+m)*255,(b2+m)*255]; }

const sty = P.style, en = cl(P.energy,0,1), dr = cl(P.dry,0,1);
const Hh = ((P.hue%360)+360)%360, tt = K.t;
const bp = sty==='blueprint', flood = sty==='flooded', salt = sty==='saltpan', noc = sty==='nocturne';

// ---- camera ----
const vy = cl(P.y,.18,.78)*height, vx = cl(P.x,.05,.95)*width;
const f = u*.92, H0 = 1;
const CS = .30*cl(P.scale,.35,2.4);          // plate size in world units

// ---- perpetual scroll ----
if (S.z == null) S.z = 0;
if (S.pt == null || K.t < S.pt) S.pt = K.t;
const dt = cl(K.t - S.pt, 0, .1); S.pt = K.t;
S.z += dt * P.speed * (.11 + .16*K.intensity) * (.55 + .6*en);
const zoff = S.z;

// the sun walks on incommensurate rates: every plate lip trades highlight for shadow
const sunA = 2.1 + .55*Math.sin(tt*.0271) + .22*Math.sin(tt*.0633+1.4);
const sunX2 = Math.cos(sunA), sunZ2 = Math.sin(sunA);
const heat = .78 + .12*Math.sin(tt*.083) + .06*Math.sin(tt*.197+1.1) + K.swell*.08 + (A.lowmid||0)*.12;
const glow = (.42+.58*en)*heat;

// ---- palette ----
let mudD, mudL, crackC, saltC, hazeC;
if (bp)        { mudD=[212,74,14]; mudL=[190,44,78]; crackC=[214,82,7];  saltC=[186,50,94]; hazeC=[202,44,32]; }
else if (flood){ mudD=[Hh+180,26,16]; mudL=[Hh+168,14,58]; crackC=[Hh+186,34,10]; saltC=[Hh+20,6,94]; hazeC=[Hh+150,12,60]; }
else if (salt) { mudD=[Hh+16,10,42]; mudL=[Hh+22,4,90];  crackC=[Hh+10,18,30]; saltC=[Hh+26,2,99]; hazeC=[Hh+24,5,80]; }
else if (noc)  { mudD=[Hh+206,20,9]; mudL=[Hh+214,10,38]; crackC=[Hh+210,26,5]; saltC=[Hh+216,6,62]; hazeC=[Hh+212,14,34]; }
else           { mudD=[Hh-4,34,22];  mudL=[Hh+8,20,74];  crackC=[Hh-10,42,13]; saltC=[Hh+18,4,96]; hazeC=[Hh+14,14,58]; }
const cMd = hsv(mudD[0], mudD[1]/100, mudD[2]/100);
const cMl = hsv(mudL[0], mudL[1]/100, mudL[2]/100);
const cCk = hsv(crackC[0], crackC[1]/100, crackC[2]/100);
const cSa = hsv(saltC[0], saltC[1]/100, saltC[2]/100);
const cHz = hsv(hazeC[0], hazeC[1]/100, hazeC[2]/100);

const BWb = 176, BHb = Math.max(44, Math.round(BWb*height/width));
if (!S.g || S.bk !== BWb+'x'+BHb){ if(S.g){ try{S.g.remove();}catch(e){} }
  S.g = createGraphics(BWb,BHb); S.g.pixelDensity(1); S.bk = BWb+'x'+BHb; }
const g = S.g; g.loadPixels(); const px = g.pixels;

const AL = P.alpha/100;
const j0 = Math.max(0, Math.floor((vy/height)*BHb));
for (let j=0;j<j0;j++) for (let i=0;i<BWb;i++) px[4*(j*BWb+i)+3] = 0;

// Worley F2-F1: gives cells whose walls meet at ~120 degrees — the real geometry of a
// desiccation net. Jittered sites, so no two plates are alike.
function cell(X, Z, s){
  const gx = Math.floor(X/s), gz = Math.floor(Z/s);
  let f1 = 1e9, f2 = 1e9, id1 = 0;
  for (let a=-1;a<=1;a++) for (let b=-1;b<=1;b++){
    const cx2 = gx+a, cz2 = gz+b;
    const jx = hsh(cx2*3+1, cz2*7+2), jz = hsh(cx2*5+3, cz2*11+4);
    const px2 = (cx2+jx)*s, pz2 = (cz2+jz)*s;
    const d = Math.sqrt((X-px2)*(X-px2) + (Z-pz2)*(Z-pz2));
    if (d < f1){ f2 = f1; f1 = d; id1 = cx2*7919 + cz2*104729; }
    else if (d < f2) f2 = d;
  }
  return [f2-f1, id1, f1, f2];
}

for (let j=j0;j<BHb;j++){
  const sy = (j+.5)/BHb*height, dy = sy - vy;
  if (dy < .35){ for (let i=0;i<BWb;i++) px[4*(j*BWb+i)+3] = 0; continue; }
  const Z = f*H0/dy, wz = Z + zoff;
  const far = cl((Z-1.1)/9, 0, 1);
  const det = cl(1 - far*1.05, .04, 1);
  for (let i=0;i<BWb;i++){
    const sx = (i+.5)/BWb*width, X = (sx-vx)*Z/f;
    const o = 4*(j*BWb+i);
    // domain warp: the net wanders, so the plates are irregular, never a lattice
    const wxx = X + (fbm(X*1.1+3.3, wz*1.1)-.5)*CS*.55;
    const wzz = wz + (fbm(X*1.1-7.7, wz*1.1+2.2)-.5)*CS*.55;
    // primary net + a finer second-generation net inside the plates (mud cracks twice)
    const C1 = cell(wxx, wzz, CS);
    const C2 = cell(wxx*1.0, wzz*1.0, CS*.34);
    const q = hsh(C1[1]|0, (C1[1]>>3)|0);
    // ---- the crack: F2-F1 is ~0 on the cell wall ----
    const cw = (.030 + dr*.055)*CS;
    const crack1 = cl(1 - C1[0]/cw, 0, 1);
    const crack2 = cl(1 - C2[0]/(cw*.42), 0, 1)*cl(dr*1.5-.35, 0, 1)*.62;
    const crack = Math.max(crack1, crack2);
    // ---- CURL: the plate lifts its edges off the bed as it dries. This is the whole read:
    // a lip in the sun is bright, the bed just beyond it is in shadow. ----
    const toEdge = cl(C1[0]/(CS*.55), 0, 1);            // 0 at the wall, 1 at the plate centre
    const curl = Math.pow(1-toEdge, 2.2)*dr;            // how high this point has lifted
    // the lip's normal tips away from the plate centre -> lambert against the walking sun
    const gxn = (cell(wxx+CS*.06, wzz, CS)[0] - C1[0])/(CS*.06);
    const gzn = (cell(wxx, wzz+CS*.06, CS)[0] - C1[0])/(CS*.06);
    const nl = Math.sqrt(gxn*gxn+gzn*gzn)+1e-4;
    const lamb = cl(.50 + ((gxn/nl)*sunX2 + (gzn/nl)*sunZ2)*curl*1.5, 0, 1.5);
    // the shadow the lifted lip throws onto the bed on its lee side
    const shadow = cl(-((gxn/nl)*sunX2 + (gzn/nl)*sunZ2), 0, 1)*curl*(.5+en*.5);
    let lum = (.34 + q*.20) * (.50 + lamb*.62) * (1 + curl*glow*.30);
    lum *= 1 - shadow*.55;
    lum *= 1 - crack*(.60 - dr*.12);                    // the crack itself is a dark slot
    // mud grain + the ghost of the last ripples the water left
    const rip = .5+.5*Math.sin(wzz*7.0 + Math.sin(wxx*2.1)*1.7);
    const grain = (fbm(X*26, wz*26)*.6 + rip*.4)*det + (1-det)*.5;
    lum *= .84 + grain*.30;
    lum = cl(lum, 0, 1.4);
    let r = cMd[0]+(cMl[0]-cMd[0])*lum, g2 = cMd[1]+(cMl[1]-cMd[1])*lum, b2 = cMd[2]+(cMl[2]-cMd[2])*lum;
    r += (cCk[0]-r)*crack*.72; g2 += (cCk[1]-g2)*crack*.72; b2 += (cCk[2]-b2)*crack*.72;
    // ---- efflorescence: salt creeps OUT of the cracks and rims every plate ----
    const eff = cl((1 - Math.abs(C1[0]-cw*1.5)/(cw*1.7)), 0, 1)*(.30+dr*.85)
              * cl(fbm(X*5+13.1, wz*5)*1.6-.25, 0, 1);
    r += (cSa[0]-r)*eff*.70; g2 += (cSa[1]-g2)*eff*.70; b2 += (cSa[2]-b2)*eff*.70;
    if (flood){
      // a sheet of standing water: only a millimetre deep, so the net still reads THROUGH it,
      // and it holds the sky. A broad live element across the whole plane.
      const pond = cl((fbm(X*.75+5.5, wz*.75-tt*.02)-.42)*2.6, 0, 1)*(1-dr*.55);
      const rp = .5+.5*Math.sin(wz*30 - tt*1.7 + X*9 + fbm(X*4, wz*4-tt*.5)*3.4);
      const mir = pond*(.45+rp*.55);
      r += (cHz[0]*1.5-r)*mir*.62; g2 += (cHz[1]*1.5-g2)*mir*.62; b2 += (cHz[2]*1.7-b2)*mir*.62;
    }
    if (bp){
      const on = crack > .34 ? 1 : 0;
      const v2 = .12+.10*(1-far);
      r = on? 80 : v2*40; g2 = on? 200*det+36 : v2*100; b2 = on? 248 : v2*172;
    }
    const hazeK = far*far*.85;
    r += (cHz[0]-r)*hazeK; g2 += (cHz[1]-g2)*hazeK; b2 += (cHz[2]-b2)*hazeK;
    px[o]=cl(r,0,255); px[o+1]=cl(g2,0,255); px[o+2]=cl(b2,0,255);
    px[o+3] = 255*AL*cl(1-far*far*.72, 0, 1)*cl(dy/2.2, 0, 1);
  }
}
